var t=`0511-rugelach`;var a=`world-0511`;var i=`IL`;var o=`western-asia`;var r=8;var l=65;var u={en:`Rugelach`,ua:`Ругелах`};var s={en:`A traditional dish from Israel, centered on all-purpose flour, cream cheese, walnut. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ізраїль. Основні складники: пшеничне борошно універсальне, вершковий сир, волоський горіх. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 15 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 15 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:15,i:[[`all-purpose-flour`,350,`g`],[`unsalted-butter`,130,`g`],[`cream-cheese`,175,`g`],[`white-granulated-sugar`,50,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`walnut`,150,`g`],[`ground-cinnamon`,7,`g`],[`white-granulated-sugar`,100,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:20,i:[]},{en:`Bake in a preheated 180°C oven for about 24 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 24 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:24,i:[]}];var d={slug:t,id:a,country:`IL`,region:o,servings:8,minutes:65,title:u,text:s,steps:g};export{i as country,d as default,a as id,l as minutes,o as region,r as servings,t as slug,g as steps,s as text,u as title};